% the same arrow crossed by a bar
\newcommand{\Qorthx}{\mathrel{\leftharpoondown\mkern-9mu{+}\mkern-9mu\rightharpoonup}}
% harpoon tail, cross, full arrow head (as printed in a) of the first page)
\newcommand{\Qorthxfull}{\mathrel{\leftharpoondown\mkern-9mu{+}\mkern-9mu\rightarrow}}
% couple de Quillen: double arrow crossed by a bar
\newcommand{\Qcouple}{\mathrel{\leftarrow\mkern-9mu{+}\mkern-9mu\rightarrow}}
% closed couple: long double arrow
\newcommand{\clos}{\longleftrightarrow}
% long arrow with small head
\newcommand{\fl}{\longrightarrow}

\begin{document}

\newcommand{\printedpage}[1]{\marginpar{\footnotesize p.~#1}}
\newcommand{\msp}[1]{\marginpar{\footnotesize [#1]}}
% printed notation
\newcommand{\M}{\mathcal{M}}
\newcommand{\Fl}{\mathrm{Fl}}
\newcommand{\Ho}{\mathrm{Ho}}
\newcommand{\cc}{\mathrm{c}}
% double-headed arrow of (2.1.4)
\newcommand{\ddarr}{\mathrel{\twoheadleftarrow\joinrel\twoheadrightarrow}}
% harpoon arrow of p. 11 (orthogonality)
\newcommand{\harp}{\mathrel{\leftharpoondown\joinrel\relbar\joinrel\rightharpoonup}}
% footnote marks printed as superscript (n) in the text, n in the note
\makeatletter
\renewcommand\@makefnmark{\hbox{\@textsuperscript{\normalfont(\@thefnmark)}}}
\renewcommand\@makefntext[1]{\noindent\hbox{\@textsuperscript{\normalfont\@thefnmark}}#1}
\newcommand{\Qcouple}{\mathrel{\leftarrow\mkern-9mu{+}\mkern-9mu\rightarrow}}
\makeatother

